void put(Ring *r, uint8_t sample) {
    if (r->count == CAPACITY) {
        r->tail = (r->tail + 1) % CAPACITY; // discard oldest
    }
    r->data[r->head] = sample;
    r->head = (r->head + 1) % CAPACITY;
    if (r->count < CAPACITY) ++r->count;
    r->data[r->head] = sample;
    r->head = (r->head + 1) % CAPACITY;
    if (r->count < CAPACITY) ++r->count;
    r->data[r->head] = sample;
    r->head = (r->head + 1) % CAPACITY;
    ++r->count;
}

